$('#inventoryBody').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const row=inventoryRows.find(v=>v.id===b.dataset.id);if(!row)return;if(b.classList.contains('editInventory')){inventoryModal(row);return}if(b.classList.contains('deleteInventory')){if(!confirm(`Delete ${row.productName} · ${row.color} · ${row.size}?`))return;try{await api('/api/admin/inventory/'+encodeURIComponent(row.id),{method:'DELETE'});toast('Stock variant deleted.');await loadInventory()}catch(err){toast(err.message,true)}}});
const stockSizes=['XS','S','M','L','XL','XXL','XXXL','Free Size','One Size','Other'];
async function bulkInventoryModal(){if(!has('products.manage'))return;await loadInventory();const productOptions=products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('#modalHost').innerHTML=`<div class="modalback"><section class="modal" style="width:min(760px,100%)"><div class="modalhead"><h2>Bulk stock update · one colour</h2><button class="btn" data-close>✕</button></div><p class="muted">Select a product and colour once, then update quantities for several sizes together. Existing combinations are updated; new ones are created.</p><form id="bulkInventoryForm" class="formgrid"><div class="formfield full"><label>Product</label><select name="productId" required>${productOptions}</select></div><div class="formfield full"><label>Colour</label><select name="color" required><option value="">Select a product first</option></select></div><div class="formfield full"><label>Size quantities</label><div class="tablewrap"><table style="min-width:520px"><thead><tr><th>Size</th><th>SKU (optional)</th><th>Quantity</th></tr></thead><tbody>${stockSizes.map(size=>`<tr><td><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="sizeEnabled" value="${esc(size)}" style="min-width:auto">${esc(size)}</label></td><td><input name="sku_${esc(size)}" maxlength="80" placeholder="Optional"></td><td><input name="qty_${esc(size)}" type="number" min="0" max="1000000" step="1" value="0"></td></tr>`).join('')}</tbody></table></div></div><div class="formfield full" style="display:flex;justify-content:end;gap:8px"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn gold">Save all selected sizes</button></div></form></section></div>`;$('#modalHost').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modalHost').innerHTML='');const form=$('#bulkInventoryForm');function prefillBulkRows(){const productId=form.elements.productId.value,color=form.elements.color.value.trim().toLowerCase();for(const size of stockSizes){const row=inventoryRows.find(v=>String(v.productId)===String(productId)&&String(v.color).trim().toLowerCase()===color&&String(v.size).trim().toLowerCase()===size.toLowerCase());const checkbox=form.querySelector(`input[name=\"sizeEnabled\"][value=\"${CSS.escape(size)}\"]`);if(checkbox)checkbox.checked=!!row;const qtyInput=form.elements['qty_'+size],skuInput=form.elements['sku_'+size];if(qtyInput)qtyInput.value=row?Number(row.quantity):0;if(skuInput)skuInput.value=row?.sku||''}}function renderBulkSizes(){const prod=products.find(x=>String(x.id)===String(form.elements.productId.value));const configured=prod?.sizesByColor||{};const color=form.elements.color.value;const key=Object.keys(configured).find(k=>k.toLowerCase()===String(color).toLowerCase());const sizeSet=Array.isArray(configured[key])?configured[key]:[];const rows=form.querySelector('tbody');rows.innerHTML=sizeSet.map(size=>`<tr><td><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="sizeEnabled" value="${esc(size)}" style="min-width:auto">${esc(size)}</label></td><td><input name="sku_${esc(size)}" maxlength="80" placeholder="Optional"></td><td><input name="qty_${esc(size)}" type="number" min="0" max="1000000" step="1" value="0"></td></tr>`).join('')||'<tr><td colspan="3" class="muted">No sizes configured for this colour.</td></tr>';prefillBulkRows()}function updateBulkChoices(){const prod=products.find(x=>String(x.id)===String(form.elements.productId.value));const colors=(prod?.colors||[]).map(c=>typeof c==='string'?c:(c.name||c.color||c.colour||'')).filter(Boolean);form.elements.color.innerHTML=colors.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')||'<option value="">No colours configured</option>';renderBulkSizes()}form.elements.productId.addEventListener('change',updateBulkChoices);form.elements.color.addEventListener('change',renderBulkSizes);updateBulkChoices();form.onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),enabled=fd.getAll('sizeEnabled');if(!enabled.length)return toast('Select at least one size.',true);const variants=enabled.map(size=>({size,sku:String(fd.get('sku_'+size)||''),quantity:Number(fd.get('qty_'+size))}));if(variants.some(v=>!Number.isInteger(v.quantity)||v.quantity<0||v.quantity>1000000))return toast('Enter whole-number quantities between 0 and 1,000,000.',true);try{const result=await api('/api/admin/inventory/bulk',{method:'POST',body:JSON.stringify({productId:fd.get('productId'),color:String(fd.get('color')).trim(),variants})});$('#modalHost').innerHTML='';toast(`${result.saved} size quantities saved successfully.`);await loadInventory();await loadProducts()}catch(err){toast(err.message,true)}}}

let banners=[];
async function loadBanners(){if(!currentUser?.isOwner)return;try{const d=await api('/api/admin/banners');banners=d.banners||[];renderBanners()}catch(e){toast(e.message,true)}}
function renderBanners(){const root=$('#bannerList');if(!root)return;root.innerHTML=banners.map(b=>`<article class="card" style="padding:0;overflow:hidden"><div style="height:125px;background:var(--surface2);overflow:hidden">${b.imageUrl?`<img src="${esc(b.imageUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" style="width:100%;height:100%;object-fit:cover">`:''}</div><div style="padding:15px"><div class="cardtitle"><div><h2>${esc(b.title)}</h2><p>${esc(b.subtitle||'No subtitle')}</p></div><span class="pill ${b.active?'good':'bad'}">${b.active?'Active':'Inactive'}</span></div><small class="muted">Order: ${Number(b.sortOrder)||0}</small><div class="table-actions" style="margin-top:12px"><button class="btn small editBanner" data-id="${esc(b.id)}">Edit</button><button class="btn small toggleBanner" data-id="${esc(b.id)}">${b.active?'Deactivate':'Activate'}</button><button class="btn small danger deleteBanner" data-id="${esc(b.id)}">Delete</button></div></div></article>`).join('')||'<p class="empty">No sales banners yet. Add your first promotion.</p>'}
function bannerModal(existing=null){if(!currentUser?.isOwner)return;$('#modalHost').innerHTML=`<div class="modalback"><section class="modal"><div class="modalhead"><h2>${existing?'Edit sales banner':'Create sales banner'}</h2><button class="btn" data-close>✕</button></div><form id="bannerForm" class="formgrid"><div class="formfield full"><label>Heading</label><input name="title" required maxlength="100" value="${esc(existing?.title||'')}"></div><div class="formfield full"><label>Supporting text</label><textarea name="subtitle" rows="2" maxlength="220">${esc(existing?.subtitle||'')}</textarea></div><div class="formfield full"><label>Background image URL (HTTPS, optional)</label><input name="imageUrl" type="url" placeholder="https://..." value="${esc(existing?.imageUrl||'')}"></div><div class="formfield"><label>Button text</label><input name="buttonText" maxlength="40" placeholder="SHOP NOW" value="${esc(existing?.buttonText||'')}"></div><div class="formfield"><label>Button link</label><input name="buttonUrl" maxlength="500" placeholder="#shop or https://..." value="${esc(existing?.buttonUrl||'')}"></div><div class="formfield"><label>Display order (lower first)</label><input name="sortOrder" type="number" min="0" max="10000" step="1" value="${Number(existing?.sortOrder)||0}"></div><div class="formfield"><label><input name="active" type="checkbox" style="min-width:auto" ${existing?.active!==false?'checked':''}> Show on storefront</label></div><div class="formfield full" style="display:flex;justify-content:end;gap:8px"><button type="button" class="btn" data-close>Cancel</button><button class="btn gold" type="submit">${existing?'Save changes':'Create banner'}</button></div></form></section></div>`;$('#modalHost').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modalHost').innerHTML='');$('#bannerForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),body={title:fd.get('title'),subtitle:fd.get('subtitle'),imageUrl:fd.get('imageUrl'),buttonText:fd.get('buttonText'),buttonUrl:fd.get('buttonUrl'),sortOrder:Number(fd.get('sortOrder')),active:f.elements.active.checked};try{await api(existing?'/api/admin/banners/'+encodeURIComponent(existing.id):'/api/admin/banners',{method:existing?'PATCH':'POST',body:JSON.stringify(body)});$('#modalHost').innerHTML='';toast(existing?'Banner updated.':'Banner created.');await loadBanners()}catch(err){toast(err.message,true)}}}
$('#bannerList').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const banner=banners.find(x=>x.id===b.dataset.id);if(!banner)return;if(b.classList.contains('editBanner'))return bannerModal(banner);try{if(b.classList.contains('toggleBanner'))await api('/api/admin/banners/'+encodeURIComponent(banner.id),{method:'PATCH',body:JSON.stringify({active:!banner.active})});else if(b.classList.contains('deleteBanner')){if(!confirm(`Delete banner “${banner.title}”?`))return;await api('/api/admin/banners/'+encodeURIComponent(banner.id),{method:'DELETE'})}toast('Banner updated.');await loadBanners()}catch(err){toast(err.message,true)}});

async function loadStaff(){try{const d=await api('/api/admin/staff');staff=d.staff||[];$('#staffBody').innerHTML=staff.map(u=>`<tr><td><strong>${esc(u.displayName)}</strong><br><span class="muted">@${esc(u.username)}</span></td><td><select class="field staffRole" data-id="${esc(u.id)}"><option value="staff" ${u.role==='staff'?'selected':''}>Staff</option><option value="manager" ${u.role==='manager'?'selected':''}>Manager</option></select></td><td>${u.active?'<span class="pill good">Active</span>':'<span class="pill bad">Disabled</span>'}</td><td>${esc(date(u.createdAt))}</td><td><div class="table-actions"><button class="btn small saveStaff" data-id="${esc(u.id)}">Save role</button><button class="btn small editPermissions" data-id="${esc(u.id)}">Permissions</button><button class="btn small" data-password="${esc(u.id)}">Reset password</button><button class="btn small ${u.active?'danger':''} toggleStaff" data-id="${esc(u.id)}">${u.active?'Disable':'Enable'}</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No team accounts yet. Create one for a trusted teammate.</td></tr>'}catch(e){toast(e.message,true)}}
$('#staffBody').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const u=staff.find(x=>x.id===b.dataset.id);if(!u)return;try{if(b.classList.contains('editPermissions')){permissionModal(u);return}else if(b.classList.contains('saveStaff')){const role=$(`.staffRole[data-id="${CSS.escape(u.id)}"]`).value;await api('/api/admin/staff/'+u.id,{method:'PATCH',body:JSON.stringify({role})});toast('Role updated.')}else if(b.classList.contains('toggleStaff')){await api('/api/admin/staff/'+u.id,{method:'PATCH',body:JSON.stringify({active:!u.active})});toast('Account status updated.')}else if(b.dataset.password){const password=prompt('Enter a new password (minimum 10 characters):');if(password===null)return;if(password.length<10)return toast('Password must be at least 10 characters.',true);await api('/api/admin/staff/'+u.id,{method:'PATCH',body:JSON.stringify({password})});toast('Password reset.')}await loadStaff()}catch(err){toast(err.message,true)}});
function staffModal(){if(!has('staff.manage'))return;$('#modalHost').innerHTML=`<div class="modalback"><section class="modal"><div class="modalhead"><h2>Add team member</h2><button class="btn" data-close>✕</button></div><form id="staffForm" class="formgrid"><div class="formfield"><label>Display name</label><input name="displayName" required minlength="2" maxlength="100"></div><div class="formfield"><label>Username</label><input name="username" required minlength="3" maxlength="60" pattern="[A-Za-z0-9._-]+"></div><div class="formfield"><label>Role</label><select name="role"><option value="staff">Staff</option><option value="manager">Manager</option></select></div><div class="formfield"><label>Temporary password (10+ characters)</label><input name="password" type="password" minlength="10" required autocomplete="new-password"></div><div class="formfield full"><p class="muted" style="font-size:12px;margin:0">Share the temporary password securely and ask the teammate to change it through an approved process. Do not reuse your owner password.</p></div><div class="formfield full" style="display:flex;flex-direction:row;justify-content:end;gap:8px"><button type="button" class="btn" data-close>Cancel</button><button type="submit" class="btn gold">Create account</button></div></form></section></div>`;$('#modalHost').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modalHost').innerHTML='');$('#staffForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/admin/staff',{method:'POST',body:JSON.stringify(body)});$('#modalHost').innerHTML='';toast('Team member created.');await loadStaff()}catch(err){toast(err.message,true)}}}
const permissionLabels=[['dashboard.view','View dashboard'],['orders.view','View orders'],['orders.update','Update order status'],['orders.cancel','Cancel orders'],['orders.payment.receive','Record COD payment received'],['products.view','View products'],['products.manage','Manage products'],['customers.view','View customer profiles and order history'],['analytics.view','View analytics'],['audit.view','View activity log']];
function permissionModal(user){if(!currentUser?.isOwner)return;const selected=new Set(user.permissions||[]);$('#modalHost').innerHTML=`<div class="modalback"><section class="modal"><div class="modalhead"><h2>Permissions · ${esc(user.displayName)}</h2><button class="btn" data-close>✕</button></div><p class="notice">Only the owner can change staff permissions. Offers, coupon codes and staff-account management remain owner-only and cannot be delegated.</p><form id="permissionsForm" class="formgrid">${permissionLabels.map(([id,label])=>`<label class="formfield full" style="display:flex;align-items:center;gap:10px"><input type="checkbox" name="permission" value="${id}" ${selected.has(id)?'checked':''} style="min-width:auto">${label}</label>`).join('')}<div class="formfield full" style="display:flex;justify-content:end;gap:8px"><button type="button" class="btn" data-close>Cancel</button><button class="btn gold" type="submit">Save permissions</button></div></form></section></div>`;$('#modalHost').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modalHost').innerHTML='');$('#permissionsForm').onsubmit=async e=>{e.preventDefault();const permissions=[...e.target.querySelectorAll('input[name="permission"]:checked')].map(x=>x.value);try{await api('/api/admin/staff/'+encodeURIComponent(user.id),{method:'PATCH',body:JSON.stringify({permissions})});$('#modalHost').innerHTML='';toast('Permissions saved.');await loadStaff()}catch(err){toast(err.message,true)}}}
let offers=[];
async function loadOffers(){if(!currentUser?.isOwner)return;try{const d=await api('/api/admin/offers');offers=d.offers||[];$('#offersBody').innerHTML=offers.map(o=>`<tr><td><strong>${esc(o.title)}</strong><br><span class="muted">Created ${esc(date(o.createdAt))}</span></td><td><code>${esc(o.code)}</code> <button class="btn small copyOffer" data-code="${esc(o.code)}">Copy</button></td><td>${o.discountType==='percent'?`${Number(o.discountValue)}% off`:`${esc(money(o.discountValue))} off`}</td><td>Minimum ${esc(money(o.minimumSubtotal||0))}<br><span class="muted">${o.expiresAt?'Expires '+esc(date(o.expiresAt)):'No expiry'}</span></td><td>${o.active?'<span class="pill good">Active</span>':'<span class="pill bad">Inactive</span>'}<br><span class="muted">Used ${Number(o.usageCount||0)} time(s)</span></td><td><div class="table-actions"><button class="btn small editOffer" data-id="${esc(o.id)}">Edit</button><button class="btn small toggleOffer" data-id="${esc(o.id)}">${o.active?'Deactivate':'Activate'}</button><button class="btn small danger deleteOffer" data-id="${esc(o.id)}">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No offers yet. Create your first coupon code.</td></tr>'}catch(e){toast(e.message,true)}}
function offerModal(existing=null){if(!currentUser?.isOwner)return;$('#modalHost').innerHTML=`<div class="modalback"><section class="modal"><div class="modalhead"><h2>${existing?'Edit offer':'Create offer & coupon code'}</h2><button class="btn" data-close>✕</button></div><form id="offerForm" class="formgrid"><div class="formfield full"><label>Offer title</label><input name="title" required minlength="2" maxlength="100" placeholder="Launch offer" value="${esc(existing?.title||'')}"></div><div class="formfield"><label>Coupon code</label><div style="display:flex;gap:6px"><input id="offerCode" name="code" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_-]+" placeholder="AERLON10" value="${esc(existing?.code||'')}" ${existing?'readonly':''} style="flex:1">${existing?'':'<button type="button" class="btn" id="generateOfferCode">Generate</button>'}</div></div><div class="formfield"><label>Discount type</label><select name="discountType"><option value="percent" ${existing?.discountType==='percent'?'selected':''}>Percentage (%)</option><option value="fixed" ${existing?.discountType==='fixed'?'selected':''}>Fixed amount (₹)</option></select></div><div class="formfield"><label>Discount value</label><input name="discountValue" type="number" min="1" step="1" required value="${esc(existing?.discountValue??'')}"></div><div class="formfield"><label>Minimum cart subtotal (₹)</label><input name="minimumSubtotal" type="number" min="0" step="1" value="${esc(existing?.minimumSubtotal??0)}" required></div><div class="formfield"><label>Starts at (optional)</label><input name="startsAt" type="datetime-local" value="${existing?.startsAt?esc(new Date(existing.startsAt).toISOString().slice(0,16)): ''}"></div><div class="formfield"><label>Expires at (optional)</label><input name="expiresAt" type="datetime-local" value="${existing?.expiresAt?esc(new Date(existing.expiresAt).toISOString().slice(0,16)): ''}"></div><div class="formfield full" style="display:flex;justify-content:end;gap:8px"><button type="button" class="btn" data-close>Cancel</button><button class="btn gold" type="submit">${existing?'Save changes':'Create offer'}</button></div></form></section></div>`;$('#modalHost').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modalHost').innerHTML='');$('#generateOfferCode').onclick=()=>{const bytes=new Uint8Array(9);crypto.getRandomValues(bytes);$('#offerCode').value='MC'+[...bytes].map(v=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[v%32]).join('')};$('#offerForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());body.code=body.code.toUpperCase().replace(/\s+/g,'');body.discountValue=Number(body.discountValue);body.minimumSubtotal=Number(body.minimumSubtotal);for(const key of ['startsAt','expiresAt'])if(body[key])body[key]=new Date(body[key]).toISOString();else body[key]=null;try{await api(existing?('/api/admin/offers/'+encodeURIComponent(existing.id)):'/api/admin/offers',{method:existing?'PATCH':'POST',body:JSON.stringify(existing?{title:body.title,discountType:body.discountType,discountValue:body.discountValue,minimumSubtotal:body.minimumSubtotal,startsAt:body.startsAt,expiresAt:body.expiresAt}:body)});$('#modalHost').innerHTML='';toast(existing?'Offer updated.':'Offer and coupon created.');await loadOffers()}catch(err){toast(err.message,true)}}}
$('#offersBody').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.classList.contains('copyOffer')){await navigator.clipboard.writeText(b.dataset.code);toast('Coupon code copied.');return}const offer=offers.find(o=>o.id===b.dataset.id);if(!offer)return;if(b.classList.contains('editOffer')){offerModal(offer);return}else if(b.classList.contains('toggleOffer'))await api('/api/admin/offers/'+encodeURIComponent(offer.id),{method:'PATCH',body:JSON.stringify({active:!offer.active})});else if(b.classList.contains('deleteOffer')){if(!confirm(`Delete coupon ${offer.code}?`))return;await api('/api/admin/offers/'+encodeURIComponent(offer.id),{method:'DELETE'})}toast('Offer updated.');await loadOffers()}catch(err){toast(err.message,true)}});
async function loadAudit(){try{const d=await api('/api/admin/audit');$('#auditList').innerHTML=(d.events||[]).map(a=>`<div class="audititem"><strong>${esc(a.action)} · ${esc(a.actor)} <span class="pill">${esc(a.role)}</span></strong><p>${esc(date(a.at))} · ${esc(JSON.stringify(a.details||{}))}</p></div>`).join('')||'<p class="muted">No activity recorded yet.</p>'}catch(e){toast(e.message,true)}}
