async function loadHeaderSettings(){if(!currentUser?.isOwner)return;try{const d=await api('/api/admin/storefront/header');const h=d.header||{};const f=$('#headerSettingsForm');if(!f)return;for(const key of ['announcement','brandText','tagline','logoUrl'])f.elements[key].value=h[key]||'';f.elements.showAnnouncement.checked=h.showAnnouncement!==false;f.elements.showTagline.checked=h.showTagline!==false}catch(e){toast(e.message,true)}}
$('#headerSettingsForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const body={announcement:f.elements.announcement.value,brandText:f.elements.brandText.value,tagline:f.elements.tagline.value,logoUrl:f.elements.logoUrl.value,showAnnouncement:f.elements.showAnnouncement.checked,showTagline:f.elements.showTagline.checked};try{await api('/api/admin/storefront/header',{method:'PUT',body:JSON.stringify(body)});toast('Storefront header settings saved. Refresh the storefront to see the changes.')}catch(err){toast(err.message,true)}});

let footerColumnsDraft=[];
function renderFooterColumns(){
  const host=$('#footerColumnsEditor');if(!host)return;
  host.innerHTML=footerColumnsDraft.map((column,index)=>`<section class="footer-column-card" data-footer-column="${index}"><div class="footer-column-head"><input data-footer-column-title="${index}" maxlength="50" aria-label="Column heading" value="${esc(column.title||'')}"><button type="button" class="btn danger small" data-footer-remove-column="${index}" aria-label="Remove column">Remove</button></div><div>${(column.links||[]).map((link,linkIndex)=>`<div class="footer-link-row"><input data-footer-link-label="${index}:${linkIndex}" maxlength="60" aria-label="Link label" placeholder="Link label" value="${esc(link.label||'')}"><input data-footer-link-url="${index}:${linkIndex}" maxlength="1200" aria-label="Link URL or TRACK" placeholder="https://... or #section or TRACK" value="${esc(link.action==='track'?'TRACK':(link.url||''))}"><button type="button" class="btn danger small" data-footer-remove-link="${index}:${linkIndex}" aria-label="Remove link">×</button></div>`).join('')}</div><div class="footer-column-actions"><button type="button" class="btn small" data-footer-add-link="${index}" ${column.links.length>=12?'disabled':''}>＋ Add link</button><span class="muted">${column.links.length}/12 links</span></div></section>`).join('')||'<p class="empty">No footer columns yet. Add a column to begin.</p>';
}
$('#footerColumnsEditor')?.addEventListener('input',event=>{
  const el=event.target;
  if(el.dataset.footerColumnTitle!==undefined){const i=Number(el.dataset.footerColumnTitle);if(footerColumnsDraft[i])footerColumnsDraft[i].title=el.value;return;}
  if(el.dataset.footerLinkLabel!==undefined||el.dataset.footerLinkUrl!==undefined){const key=(el.dataset.footerLinkLabel??el.dataset.footerLinkUrl).split(':').map(Number);const [i,j]=key;if(!footerColumnsDraft[i]?.links?.[j])return;if(el.dataset.footerLinkLabel!==undefined)footerColumnsDraft[i].links[j].label=el.value;else{const value=el.value.trim();footerColumnsDraft[i].links[j]=value.toUpperCase()==='TRACK'?{...footerColumnsDraft[i].links[j],action:'track',url:''}:{...footerColumnsDraft[i].links[j],action:'',url:el.value};}}
});
$('#footerColumnsEditor')?.addEventListener('click',event=>{
  const button=event.target.closest('button');if(!button)return;
  if(button.dataset.footerAddLink!==undefined){const i=Number(button.dataset.footerAddLink);if(footerColumnsDraft[i]&&footerColumnsDraft[i].links.length<12)footerColumnsDraft[i].links.push({label:'',url:''});renderFooterColumns();return;}
  if(button.dataset.footerRemoveLink!==undefined){const [i,j]=button.dataset.footerRemoveLink.split(':').map(Number);footerColumnsDraft[i]?.links.splice(j,1);renderFooterColumns();return;}
  if(button.dataset.footerRemoveColumn!==undefined){const i=Number(button.dataset.footerRemoveColumn);footerColumnsDraft.splice(i,1);renderFooterColumns();}
});
$('#addFooterColumn')?.addEventListener('click',()=>{if(footerColumnsDraft.length>=4)return toast('You can add up to 4 footer columns.',true);footerColumnsDraft.push({id:`column-${Date.now()}`,title:'NEW COLUMN',links:[]});renderFooterColumns();});
async function loadFooterSettings(){
  if(!currentUser?.isOwner)return;
  try{
    const data=await api('/api/admin/storefront/footer');const f=$('#footerSettingsForm');if(!f)return;const d=data.footer||{};
    for(const key of ['brandText','tagline','intro','logoUrl','newsletterKicker','newsletterTitle','newsletterDescription','newsletterButtonText','newsletterConsentText','copyrightText'])f.elements[key].value=d[key]||'';
    for(const key of ['enabled','showBrand','showTagline','showIntro','newsletterEnabled','trustEnabled','backToTopEnabled'])f.elements[key].checked=d[key]!==false;
    for(const key of ['instagram','facebook','youtube','pinterest','x','whatsapp'])f.elements[key].value=d.socials?.[key]||'';
    (d.trustItems||[]).forEach((value,index)=>{if(f.elements[`trustItem${index}`])f.elements[`trustItem${index}`].value=value||''});
    footerColumnsDraft=Array.isArray(d.columns)?d.columns.map(c=>({id:c.id,title:c.title,links:(c.links||[]).map(l=>({...l}))})):[];renderFooterColumns();
  }catch(error){toast(error.message,true)}
}
$('#footerSettingsForm')?.addEventListener('submit',async event=>{
  event.preventDefault();const f=event.currentTarget;const submit=$('#saveFooterSettings');submit.disabled=true;
  const body={enabled:f.elements.enabled.checked,showBrand:f.elements.showBrand.checked,brandText:f.elements.brandText.value,tagline:f.elements.tagline.value,intro:f.elements.intro.value,logoUrl:f.elements.logoUrl.value,showTagline:f.elements.showTagline.checked,showIntro:f.elements.showIntro.checked,socials:{instagram:f.elements.instagram.value,facebook:f.elements.facebook.value,youtube:f.elements.youtube.value,pinterest:f.elements.pinterest.value,x:f.elements.x.value,whatsapp:f.elements.whatsapp.value},columns:footerColumnsDraft,newsletterEnabled:f.elements.newsletterEnabled.checked,newsletterKicker:f.elements.newsletterKicker.value,newsletterTitle:f.elements.newsletterTitle.value,newsletterDescription:f.elements.newsletterDescription.value,newsletterButtonText:f.elements.newsletterButtonText.value,newsletterConsentText:f.elements.newsletterConsentText.value,trustEnabled:f.elements.trustEnabled.checked,trustItems:[f.elements.trustItem0.value,f.elements.trustItem1.value,f.elements.trustItem2.value],copyrightText:f.elements.copyrightText.value,backToTopEnabled:f.elements.backToTopEnabled.checked};
  try{const saved=await api('/api/admin/storefront/footer',{method:'PUT',body:JSON.stringify(body)});footerColumnsDraft=saved.footer.columns;renderFooterColumns();toast('Footer settings saved. Refresh the storefront to see the changes.');}catch(error){toast(error.message,true)}finally{submit.disabled=false;}
});


let footerSubscribersCache=[];
async function loadFooterSubscribers(){
  if(!currentUser?.isOwner)return;
  const body=$('#footerSubscribersBody');if(body)body.innerHTML='<tr><td colspan="3" class="empty">Loading subscribers…</td></tr>';
  try{
    const data=await api('/api/admin/newsletter/subscribers');footerSubscribersCache=Array.isArray(data.subscribers)?data.subscribers:[];
    if(body)body.innerHTML=footerSubscribersCache.map(item=>`<tr><td>${esc(item.email)}</td><td><span class="pill ${item.status==='subscribed'?'good':'muted'}">${esc(item.status)}</span></td><td>${esc(date(item.consentAt))}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No newsletter subscribers yet.</td></tr>';
    $('#exportFooterSubscribers').disabled=!footerSubscribersCache.length;
  }catch(error){if(body)body.innerHTML=`<tr><td colspan="3" class="empty">${esc(error.message)}</td></tr>`;toast(error.message,true)}
}
$('#loadFooterSubscribers')?.addEventListener('click',loadFooterSubscribers);
$('#exportFooterSubscribers')?.addEventListener('click',()=>{
  if(!footerSubscribersCache.length)return;
  const quote=value=>'"'+String(value??'').replace(/"/g,'""')+'"';
  const rows=[['Email','Status','Consent date'],...footerSubscribersCache.map(item=>[item.email,item.status,item.consentAt])];
  const csv='\uFEFF'+rows.map(row=>row.map(quote).join(',')).join('\r\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='AERLON-newsletter-subscribers.csv';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);
});
